BEGIN TRANSACTION;
  UPDATE accounts SET balance = balance - 100 WHERE id = 1;
  UPDATE accounts SET balance = balance + 100 WHERE id = 2;
COMMIT;
-- if the second UPDATE fails (or the app crashes between the two),
-- the transaction rolls back and account 1 keeps its original balance --
-- without a transaction, a crash here would silently lose $100

